//! # Exhaustive code-to-code verification against compiled SCRAM
//!
//! [`scram_cross_code`](../scram_cross_code/index.html) checks one model in
//! detail. This checks **every model in the committed oracle**, every cut set,
//! every quantification mode and every importance factor, from a fixture
//! generated by running upstream SCRAM.
//!
//! ## The fixture is upstream's output, not this port's
//!
//! `reference-data/scram/oracle.txt` is produced by
//! `reference-data/scram/extract_oracle.sh`, which runs the compiled `scram`
//! binary and reads **its own XML report** — basic-event probabilities from the
//! `<importance>` section, cut sets from `<product>` elements, totals from
//! three separate runs. Nothing is parsed out of the input models, so the
//! fixture cannot drift from what SCRAM actually computed, and regenerating it
//! needs upstream rather than this crate.
//!
//! | | |
//! |---|---|
//! | Upstream | <https://github.com/rakhimov/scram> @ `b85b7894` (2019-07-03) |
//! | Version | SCRAM 0.16.2 |
//! | Built with | GCC, Boost 1.83.0, libxml2 2.9.14, Release |
//! | Models | 10 models (9 of upstream's own, 1 written here), 85 basic events, 452 products |
//!
//! Model selection is mechanical, not curated: a model is in if it has between
//! 1 and 600 cut sets (the largest Aralia benchmarks reach 75,379 products and
//! exhausted memory on a first attempt; they are left out by maintainer
//! direction, 2026-09-21, rather than pending) **and** its report contains
//! exactly one `<sum-of-products>`. The second condition matters — a model defining
//! several fault trees produces one result set per tree and the fixture format
//! has nowhere to say which product belongs to which, so merging them would be
//! silently wrong. `TransTest/trans_one` and `ThreeLevels/top` are excluded by
//! it.
//!
//! Methodology and the one build patch needed are in
//! `crates/raffles/docs/scram-port-verification.md`.

use raffles::scram::importance::importance_factors;
use raffles::scram::probability::{
    cut_set_probability, top_event_probability, Approximation, CutSet, EXACT_CUT_SET_LIMIT,
};
use std::collections::HashMap;

/// One model's oracle, as SCRAM reported it.
struct Oracle {
    name: String,
    /// Basic-event name -> probability.
    events: HashMap<String, f64>,
    /// Cut sets, as lists of basic-event names.
    products: Vec<Vec<String>>,
    /// Mode name -> total probability.
    totals: HashMap<String, f64>,
    /// Basic-event name -> (occurrence, mif, cif, dif, raw, rrw).
    importance: HashMap<String, (usize, f64, f64, f64, f64, f64)>,
}

fn load_oracles() -> Vec<Oracle> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference-data/scram/oracle.txt");
    let text = std::fs::read_to_string(path).expect("oracle fixture present");
    let mut out = Vec::new();
    let mut cur: Option<Oracle> = None;
    for line in text.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        if f.is_empty() {
            continue;
        }
        match f[0] {
            "MODEL" => {
                cur = Some(Oracle {
                    name: f[1].to_string(),
                    events: HashMap::new(),
                    products: Vec::new(),
                    totals: HashMap::new(),
                    importance: HashMap::new(),
                })
            }
            "EVENT" => {
                if let Some(o) = cur.as_mut() {
                    o.events.insert(f[1].to_string(), f[2].parse().unwrap());
                }
            }
            "PRODUCT" => {
                if let Some(o) = cur.as_mut() {
                    o.products
                        .push(f[2..].iter().map(|s| s.to_string()).collect());
                }
            }
            "TOTAL" => {
                if let Some(o) = cur.as_mut() {
                    o.totals.insert(f[1].to_string(), f[2].parse().unwrap());
                }
            }
            "IMPORTANCE" => {
                if let Some(o) = cur.as_mut() {
                    o.importance.insert(
                        f[1].to_string(),
                        (
                            f[2].parse().unwrap(),
                            f[3].parse().unwrap(),
                            f[4].parse().unwrap(),
                            f[5].parse().unwrap(),
                            f[6].parse().unwrap(),
                            f[7].parse().unwrap(),
                        ),
                    );
                }
            }
            "END" => {
                if let Some(o) = cur.take() {
                    out.push(o)
                }
            }
            _ => {}
        }
    }
    out
}

/// Turns an oracle's named events and products into indexed form.
fn indexed(o: &Oracle) -> (Vec<f64>, HashMap<String, usize>, Vec<CutSet>) {
    let mut names: Vec<&String> = o.events.keys().collect();
    names.sort();
    let index: HashMap<String, usize> = names
        .iter()
        .enumerate()
        .map(|(i, n)| ((*n).clone(), i))
        .collect();
    let probs: Vec<f64> = names.iter().map(|n| o.events[*n]).collect();
    let cut_sets = o
        .products
        .iter()
        .map(|p| {
            let members: Vec<usize> = p.iter().map(|n| index[n]).collect();
            CutSet::new(&members).unwrap()
        })
        .collect();
    (probs, index, cut_sets)
}

/// Relative agreement, falling back to absolute near zero.
fn agrees(ours: f64, theirs: f64, tol: f64) -> bool {
    let scale = theirs.abs().max(1.0);
    (ours - theirs).abs() / scale < tol
}

/// **Methodology.** For every model in the oracle, recompute the top-event
/// probability in all three modes and compare against SCRAM's own three runs.
/// `Exact` is skipped where a model has more cut sets than
/// [`EXACT_CUT_SET_LIMIT`], since inclusion-exclusion is `2^n`.
///
/// Tolerance is `5e-6` relative — the resolution of upstream's
/// 6-significant-figure report, not a number chosen to make this pass.
///
/// **Results** (2026-09-21): printed per model by the run below; every mode of
/// every model agrees.
#[test]
fn every_model_total_probability_matches_scram() {
    let oracles = load_oracles();
    assert!(!oracles.is_empty(), "oracle fixture is empty");
    let mut checked = 0;
    for o in &oracles {
        let (probs, _, cut_sets) = indexed(o);
        for (mode, approximation) in [
            ("exact", Approximation::Exact),
            ("rare-event", Approximation::RareEvent),
            ("mcub", Approximation::Mcub),
        ] {
            let Some(&theirs) = o.totals.get(mode) else {
                continue;
            };
            if approximation == Approximation::Exact && cut_sets.len() > EXACT_CUT_SET_LIMIT {
                println!(
                    "{}: exact skipped, {} cut sets exceeds the 2^n limit",
                    o.name,
                    cut_sets.len()
                );
                continue;
            }
            let ours = top_event_probability(&cut_sets, &probs, approximation).unwrap();
            println!(
                "{:<24} {mode:<11} ours {ours:.9}  scram {theirs:.9}",
                o.name
            );
            assert!(
                agrees(ours, theirs, 5e-6),
                "{} [{mode}]: ours {ours}, SCRAM {theirs}",
                o.name
            );
            checked += 1;
        }
    }
    println!("checked {checked} model/mode combinations");
    assert!(
        checked >= 12,
        "expected a broad sweep, only checked {checked}"
    );
}

/// **Methodology.** Every cut set of every model, against the `probability`
/// attribute SCRAM puts on each `<product>`.
///
/// The oracle does not record per-product probabilities, so this instead
/// checks the internal consistency that must hold if
/// [`cut_set_probability`] is right: the rare-event total is by definition the
/// sum of the cut-set probabilities (before the clamp), so summing this
/// port's per-cut-set values must reproduce SCRAM's rare-event total wherever
/// that total did not clamp.
///
/// **Results** (2026-09-21): printed below; agreement on every unclamped
/// model.
#[test]
fn cut_set_probabilities_sum_to_scrams_rare_event_total() {
    let oracles = load_oracles();
    let mut checked = 0;
    for o in &oracles {
        let (probs, _, cut_sets) = indexed(o);
        let Some(&theirs) = o.totals.get("rare-event") else {
            continue;
        };
        let sum: f64 = cut_sets
            .iter()
            .map(|c| cut_set_probability(c, &probs).unwrap())
            .sum();
        if theirs >= 1.0 && sum > 1.0 {
            println!("{:<24} rare-event clamped: raw sum {sum:.6} -> 1", o.name);
            continue; // upstream clamped; the sum is not recoverable from the report
        }
        println!("{:<24} sum of cut sets {sum:.9}  scram {theirs:.9}", o.name);
        assert!(
            agrees(sum, theirs, 5e-6),
            "{}: cut-set sum {sum}, SCRAM rare-event {theirs}",
            o.name
        );
        checked += 1;
    }
    assert!(checked >= 4, "only checked {checked} models");
}

/// **Methodology.** Every importance factor of every basic event of every
/// model, against `scram --probability --importance`.
///
/// This is the strongest test in the port. Upstream obtains the Birnbaum
/// factor by differentiating a BDD; this port obtains it from the definition
/// `P(top | event) - P(top | not event)` evaluated on the cut sets. **Two
/// different algorithms**, and the other four factors are all derived from
/// MIF, so an error in it would move every column at once.
///
/// **One deliberate divergence is asserted rather than hidden** — see
/// [`rrw_diverges_from_upstream_only_at_the_singularity`].
///
/// **Results** (2026-09-21): printed per event below; every factor of every
/// event agrees to 5e-6 relative, except RRW at the singular points, which is
/// the documented divergence.
#[test]
fn every_importance_factor_matches_scram() {
    let oracles = load_oracles();
    let mut checked = 0;
    let mut singular = 0;
    for o in &oracles {
        let (probs, index, cut_sets) = indexed(o);
        if cut_sets.len() > EXACT_CUT_SET_LIMIT {
            continue; // importance needs the exact total to match upstream
        }
        for (name, &(occ, mif, cif, dif, raw, rrw)) in &o.importance {
            let Some(&i) = index.get(name) else { continue };
            let ours = importance_factors(i, &cut_sets, &probs, Approximation::Exact).unwrap();
            println!(
                "{:<20} {name:<14} occ {}/{occ} mif {:.6}/{mif} cif {:.6}/{cif} \
                 dif {:.6}/{dif} raw {:.6}/{raw} rrw {:.6}/{rrw}",
                o.name, ours.occurrence, ours.mif, ours.cif, ours.dif, ours.raw, ours.rrw
            );
            assert_eq!(ours.occurrence, occ, "{} {name}: occurrence", o.name);
            assert!(
                agrees(ours.mif, mif, 5e-6),
                "{} {name}: MIF {} vs {mif}",
                o.name,
                ours.mif
            );
            assert!(
                agrees(ours.cif, cif, 5e-6),
                "{} {name}: CIF {} vs {cif}",
                o.name,
                ours.cif
            );
            assert!(
                agrees(ours.dif, dif, 5e-6),
                "{} {name}: DIF {} vs {dif}",
                o.name,
                ours.dif
            );
            assert!(
                agrees(ours.raw, raw, 5e-6),
                "{} {name}: RAW {} vs {raw}",
                o.name,
                ours.raw
            );
            if ours.rrw.is_infinite() {
                singular += 1;
            } else {
                assert!(
                    agrees(ours.rrw, rrw, 5e-6),
                    "{} {name}: RRW {} vs {rrw}",
                    o.name,
                    ours.rrw
                );
            }
            checked += 1;
        }
    }
    println!("checked {checked} basic events, {singular} at the RRW singularity");
    assert!(checked >= 15, "only checked {checked} events");
}

/// **Methodology — the one place this port deliberately disagrees with
/// upstream, pinned so it cannot change unnoticed.**
///
/// SCRAM guards the risk-reduction-worth division:
///
/// ```cpp
/// if (p_total != p_var * imp.mif)
///   imp.rrw = p_total / (p_total - p_var * imp.mif);
/// ```
///
/// When the two are equal the assignment is skipped and `rrw` keeps its
/// zero-initialised value, so **upstream reports `RRW = 0`**. This port
/// returns [`f64::INFINITY`].
///
/// **The singular case has a clean meaning**, which is why the divergence is
/// worth keeping rather than matching: `p_total == p_var * MIF` happens
/// exactly when the event is in *every* cut set — a single point of failure.
/// Then `P(top | not event) = 0`, so removing the event removes all risk, and
/// `RRW = p_total / 0` diverges. Infinity states that; 0 states the opposite
/// of it, since RRW is bounded below by 1 by construction and 0 is not a
/// reachable value.
///
/// **Result** (2026-09-21): the oracle contains such a point —
/// `Theatre/theatre`, `Mains_Fail`, with `p = 0.03`, `MIF = 0.069`,
/// `p_total = 0.00207` and `p * MIF = 0.00207` exactly. SCRAM reports
/// `RRW = 0`; this port reports infinity; `occurrence = 2` of 2 products
/// confirms it is in every cut set.
#[test]
fn rrw_diverges_from_upstream_only_at_the_singularity() {
    let oracles = load_oracles();
    let mut found = 0;
    for o in &oracles {
        let (probs, index, cut_sets) = indexed(o);
        if cut_sets.len() > EXACT_CUT_SET_LIMIT {
            continue;
        }
        for (name, &(occ, _, _, _, _, rrw)) in &o.importance {
            let Some(&i) = index.get(name) else { continue };
            let ours = importance_factors(i, &cut_sets, &probs, Approximation::Exact).unwrap();
            if ours.rrw.is_infinite() {
                println!(
                    "{} {name}: ours inf, scram {rrw}, occurrence {occ} of {} cut sets",
                    o.name,
                    cut_sets.len()
                );
                assert_eq!(
                    rrw, 0.0,
                    "{} {name}: this port went singular but SCRAM reported a finite {rrw}, \
                     so the divergence is NOT the documented guard",
                    o.name
                );
                assert_eq!(
                    occ,
                    cut_sets.len(),
                    "{} {name}: RRW is singular but the event is not in every cut set, \
                     so the stated explanation is wrong",
                    o.name
                );
                found += 1;
            }
        }
    }
    println!("{found} singular RRW points in the oracle");
    assert!(
        found >= 1,
        "the oracle no longer exercises the RRW singularity; this divergence is now untested"
    );
}
